renderer.localClippingEnabled = true;
const CUT_Z = 1.1;
const cutPlane = new THREE.Plane(new THREE.Vector3(0, 0, -1), CUT_Z);

const NAVY = 0x1c4e80;
const DOT_NAVY = 0x12365c;

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0x9a9a9a, 1.0));
const key = new THREE.DirectionalLight(0xffffff, 0.55);
key.position.set(-4, 6, 5);
scene.add(key);

/* ── gradient texture helper (canvas top = v=1) ─────────────────────────── */
function gradTex(stops) {
  const cv = document.createElement('canvas');
  cv.width = 8; cv.height = 256;
  const g = cv.getContext('2d');
  const grd = g.createLinearGradient(0, 0, 0, 256);
  stops.forEach(s => grd.addColorStop(s[0], s[1]));
  g.fillStyle = grd; g.fillRect(0, 0, 8, 256);
  const tex = new THREE.CanvasTexture(cv);
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const blueTex = gradTex([
  [0.00, '#f4fbff'], [0.22, '#e2f2fc'], [0.50, '#b9dcf2'],
  [0.78, '#4b90c9'], [1.00, '#1f6ab0']
]);
const tanTex = gradTex([
  [0.00, '#efe2c4'], [0.45, '#e3cfa4'], [0.72, '#ddc99c'],
  [0.760, '#cdb888'], [0.855, '#cdb888'], [0.895, '#e0cc9e'], [1.00, '#eadaB4']
]);
const floorTex = gradTex([
  [0.00, '#d6c094'], [0.45, '#dcc79b'], [1.00, '#f4e6c6']
]);

/* ── dome shells ────────────────────────────────────────────────────────── */
function halfEllipsoid(a, b, c, seg) {
  const g = new THREE.SphereGeometry(1, seg, seg / 2, 0, Math.PI * 2, 0, Math.PI / 2);
  g.scale(a, b, c);
  return g;
}

const outerMat = new THREE.MeshBasicMaterial({
  map: blueTex, side: THREE.FrontSide, clippingPlanes: [cutPlane], clipShadows: false
});
const outerDome = new THREE.Mesh(halfEllipsoid(3.08, 2.08, 3.08, 96), outerMat);
scene.add(outerDome);

const innerMat = new THREE.MeshBasicMaterial({
  map: tanTex, side: THREE.BackSide, clippingPlanes: [cutPlane]
});
const innerDome = new THREE.Mesh(halfEllipsoid(3.0, 2.0, 3.0, 96), innerMat);
scene.add(innerDome);

registerInteractive(innerDome, {
  title: 'Elliptical dome',
  tooltip: 'Half-ellipsoid room',
  body: 'The room is the upper half of an ellipsoid with semi-axes a = 3 (along x), b = 2 (up) and c = 3 (depth). Its vertical cross-section through the two foci is the ellipse x²/9 + y²/4 = 1.'
});

/* ── cut-rim strip (shell thickness at the cutaway) ─────────────────────── */
(function buildRim() {
  const ki = 1 - (CUT_Z * CUT_Z) / 9;
  const ko = 1 - (CUT_Z * CUT_Z) / (3.08 * 3.08);
  const iax = 3.0 * Math.sqrt(ki), iby = 2.0 * Math.sqrt(ki);
  const oax = 3.08 * Math.sqrt(ko), oby = 2.08 * Math.sqrt(ko);
  const N = 96, pos = [], idx = [];
  for (let i = 0; i <= N; i++) {
    const a = Math.PI * i / N;
    pos.push(iax * Math.cos(a), iby * Math.sin(a), CUT_Z - 0.002);
    pos.push(oax * Math.cos(a), oby * Math.sin(a), CUT_Z - 0.002);
  }
  for (let i = 0; i < N; i++) {
    const p = i * 2;
    idx.push(p, p + 1, p + 2, p + 1, p + 3, p + 2);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  const m = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide });
  const rim = new THREE.Mesh(g, m);
  scene.add(rim);

  // faint inner highlight line of the rim
  const lp = [];
  for (let i = 0; i <= N; i++) {
    const a = Math.PI * i / N;
    lp.push(new THREE.Vector3(iax * Math.cos(a), iby * Math.sin(a), CUT_Z - 0.004));
  }
  const ln = new THREE.Line(new THREE.BufferGeometry().setFromPoints(lp),
    new THREE.LineBasicMaterial({ color: 0xe8f2fa }));
  scene.add(ln);
})();

/* ── floor + base slab ──────────────────────────────────────────────────── */
const floorGeo = new THREE.CircleGeometry(3.0, 96);
floorGeo.rotateX(-Math.PI / 2);
const floor = new THREE.Mesh(floorGeo, new THREE.MeshBasicMaterial({ map: floorTex }));
floor.position.y = 0.002;
scene.add(floor);

const lip = new THREE.Mesh(
  new THREE.CylinderGeometry(3.15, 3.15, 0.08, 96),
  new THREE.MeshLambertMaterial({ color: 0x8d8e90 })
);
lip.position.y = -0.04;
scene.add(lip);

const slab = new THREE.Mesh(
  new THREE.CylinderGeometry(3.15, 3.10, 0.37, 96),
  new THREE.MeshLambertMaterial({ color: 0x57585a })
);
slab.position.y = -0.265;
scene.add(slab);

/* ── foci ───────────────────────────────────────────────────────────────── */
const CFOC = Math.sqrt(9 - 4);           // 2.2360679...
const Fp = new THREE.Vector3(-CFOC, 0.05, 0);
const Ff = new THREE.Vector3(CFOC, 0.05, 0);
const dotMat = new THREE.MeshBasicMaterial({ color: DOT_NAVY });
const dotFp = new THREE.Mesh(new THREE.SphereGeometry(0.09, 20, 14), dotMat);
dotFp.position.copy(Fp); scene.add(dotFp);
const dotF = new THREE.Mesh(new THREE.SphereGeometry(0.09, 20, 14), dotMat);
dotF.position.copy(Ff); scene.add(dotF);

registerInteractive(dotFp, {
  title: "Focus F′ (the whisperer)",
  tooltip: "Focus F′",
  body: "F′ sits on the floor at x = −√(a²−b²) = −2.236. Sound leaving this point in any direction reflects once off the dome and converges on the other focus."
});
registerInteractive(dotF, {
  title: 'Focus F (the listener)',
  tooltip: 'Focus F',
  body: 'F sits at x = +2.236. Because |F′P| + |PF| = 2a = 6 for every point P on the ellipse, all reflected sound arrives here at the same time and in phase.'
});

/* ── rays ───────────────────────────────────────────────────────────────── */
const T_DEG = [25, 55, 80, 100, 125, 150, 168];
const UPV = new THREE.Vector3(0, 1, 0);

function tubeBetween(p1, p2, r, mat, radialSeg) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = dir.length();
  const g = new THREE.CylinderGeometry(r, r, len, radialSeg || 10, 1, true);
  const m = new THREE.Mesh(g, mat);
  m.position.copy(p1).add(p2).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(UPV, dir.clone().normalize());
  return m;
}
function coneAt(pos, dir, mat) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.22, 14), mat);
  m.position.copy(pos);
  m.quaternion.setFromUnitVectors(UPV, dir.clone().normalize());
  return m;
}

const proxyMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
const rays = [];

T_DEG.forEach((deg, i) => {
  const t = THREE.MathUtils.degToRad(deg);
  const P = new THREE.Vector3(3 * Math.cos(t), 2 * Math.sin(t), 0);
  const mat = new THREE.MeshBasicMaterial({ color: NAVY, transparent: true, opacity: 1 });
  const grp = new THREE.Group();

  const legs = [[Fp, P], [P, Ff]];
  legs.forEach(([A, B]) => {
    grp.add(tubeBetween(A, B, 0.026, mat));
    const mid = new THREE.Vector3().addVectors(A, B).multiplyScalar(0.5);
    grp.add(coneAt(mid, new THREE.Vector3().subVectors(B, A), mat));
    grp.add(tubeBetween(A, B, 0.13, proxyMat, 6));   // raycast proxy
  });

  const L1 = Fp.distanceTo(P), L2 = P.distanceTo(Ff);
  grp.userData = { index: i, P, L1, L2, mat, deg };
  scene.add(grp);
  rays.push(grp);

  registerInteractive(grp, {
    title: 'Ray ' + (i + 1) + ' — launch angle ' + deg + '°',
    tooltip: 'Ray ' + (i + 1) + ': click to isolate',
    body: 'This ray leaves F′, strikes the dome at P = (' + P.x.toFixed(2) + ', ' + P.y.toFixed(2) + ')' +
      ' and reflects to F. |F′P| + |PF| = ' + (L1 + L2).toFixed(2) + ' = 2a, the same as every other ray.',
    onClick: () => selectRay(i)
  });
});

/* ── sound pulses ───────────────────────────────────────────────────────── */
const pulseMat = new THREE.MeshBasicMaterial({ color: 0xffd166 });
const pulses = rays.map(() => {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.075, 14, 10), pulseMat);
  s.visible = false;
  scene.add(s);
  return s;
});
function makeRing(center) {
  const g = new THREE.RingGeometry(0.26, 0.34, 64);
  g.rotateX(-Math.PI / 2);
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color: 0x2f7fc4, transparent: true, opacity: 0.8, side: THREE.DoubleSide, depthWrite: false
  }));
  m.position.set(center.x, 0.03, center.z);
  m.visible = false;
  scene.add(m);
  return m;
}
const ringLaunch = makeRing(Fp);
const ringArrive = makeRing(Ff);

/* ── camera (after geometry) ────────────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 18, rollDeg: 0, heightFraction: 0.62 });

/* ── labels ─────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,\'Times New Roman\',serif;font-style:italic;';
addLabel('<span style="' + SER + '">F&prime;</span>', Fp, { fontSize: '17px', offset: [-16, 22] });
addLabel('<span style="' + SER + '">F</span>', Ff, { fontSize: '17px', offset: [18, 22] });

/* ── controls / state ───────────────────────────────────────────────────── */
let mode = 'single';        // 'single' | 'all'
let selected = 2;           // steep ray (t = 80°)
let playing = false;
let clock0 = performance.now();

const btnSingle = document.getElementById('btnSingle');
const btnAll = document.getElementById('btnAll');
const btnPulse = document.getElementById('btnPulse');
const rayBtns = document.getElementById('rayBtns');
const readout = document.getElementById('readout');

rays.forEach((g, i) => {
  const b = document.createElement('button');
  b.textContent = String(i + 1);
  b.style.padding = '3px 7px';
  b.title = 'Launch angle ' + g.userData.deg + '°';
  b.addEventListener('click', () => selectRay(i));
  rayBtns.appendChild(b);
});

function refresh() {
  rays.forEach((g, i) => {
    const full = (mode === 'all') || (i === selected);
    g.userData.mat.opacity = full ? 1.0 : 0.12;
    g.userData.mat.depthWrite = full;
  });
  btnSingle.classList.toggle('active', mode === 'single');
  btnAll.classList.toggle('active', mode === 'all');
  Array.from(rayBtns.children).forEach((b, i) =>
    b.classList.toggle('active', i === selected));
  const u = rays[selected].userData;
  readout.textContent =
    'ray ' + (selected + 1) + '  θ=' + u.deg + '°\n' +
    '|F\u2032P| = ' + u.L1.toFixed(3) + '\n' +
    '|PF|  = ' + u.L2.toFixed(3) + '\n' +
    'sum   = ' + (u.L1 + u.L2).toFixed(3) + '  = 2a';
  readout.style.whiteSpace = 'pre';
}

function selectRay(i) {
  selected = i;
  if (mode === 'all') { /* keep full fan, but highlight in readout */ }
  refresh();
}

btnSingle.addEventListener('click', () => { mode = 'single'; refresh(); });
btnAll.addEventListener('click', () => { mode = 'all'; refresh(); });

btnPulse.addEventListener('click', () => setPlaying(!playing));
function setPlaying(p) {
  playing = p;
  clock0 = performance.now();
  btnPulse.textContent = playing ? '❚❚ Pause sound pulses' : '▶ Play sound pulses from F\u2032';
  btnPulse.classList.toggle('active', playing);
  if (!playing) {
    pulses.forEach(s => s.visible = false);
    ringLaunch.visible = ringArrive.visible = false;
  }
}

/* ── demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'One whisper, one path',
    text: "A single ray leaves F\u2032 at a steep angle, strikes the inside of the dome once, and comes straight back down to F. Click any other ray to change which route is shown.",
    mode: 'single', ray: 2, play: false
  },
  {
    title: 'A different launch angle',
    text: "Choosing a shallower ray moves the bounce point far to the side, yet the reflected segment still terminates exactly at F — the curved wall always redirects the ray to the other focus.",
    mode: 'single', ray: 0, play: false
  },
  {
    title: 'The whole fan',
    text: "All seven rays at once: they leave F\u2032 in a spread of directions, bounce at seven separate points, cross one another mid-room, and every one arrives at F.",
    mode: 'all', ray: 3, play: false
  },
  {
    title: 'Sound in motion',
    text: "Playing the pulses shows why the listener hears a whisper clearly: each path has the same total length 2a = 6, so the sound reassembles at F at the same instant.",
    mode: 'all', ray: 3, play: true
  }
];
let step = 0;
const elTitle = document.getElementById('stepTitle');
const elText = document.getElementById('stepText');
const elCount = document.getElementById('stepCount');

function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  elTitle.textContent = s.title;
  elText.textContent = s.text;
  elCount.textContent = (step + 1) + ' / ' + STEPS.length;
  mode = s.mode;
  selected = s.ray;
  setPlaying(s.play);
  refresh();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(step - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(step + 1));
goToStep(0);

/* ── pulse animation loop ───────────────────────────────────────────────── */
const PERIOD = 2800;
const tmpA = new THREE.Vector3();
function tick() {
  requestAnimationFrame(tick);
  if (!playing) return;
  const u = ((performance.now() - clock0) % PERIOD) / PERIOD;
  rays.forEach((g, i) => {
    const show = (mode === 'all') || (i === selected);
    const p = pulses[i];
    p.visible = show;
    if (!show) return;
    const d = u * 6.0;
    const { P, L1, L2 } = g.userData;
    if (d <= L1) tmpA.lerpVectors(Fp, P, d / L1);
    else tmpA.lerpVectors(P, Ff, Math.min(1, (d - L1) / L2));
    p.position.copy(tmpA);
  });
  // launch ring at F', arrival ring at F
  const lw = u < 0.18 ? u / 0.18 : -1;
  ringLaunch.visible = lw >= 0;
  if (lw >= 0) {
    const s = 0.4 + lw * 2.2;
    ringLaunch.scale.set(s, 1, s);
    ringLaunch.material.opacity = 0.75 * (1 - lw);
  }
  const aw = u > 0.82 ? (u - 0.82) / 0.18 : -1;
  ringArrive.visible = aw >= 0;
  if (aw >= 0) {
    const s = 2.6 - aw * 2.2;
    ringArrive.scale.set(s, 1, s);
    ringArrive.material.opacity = 0.35 + 0.5 * aw;
  }
}
tick();
// @FIGURE_CODE_END

