  {
    title: 'Sound in motion',
    text: "The pulses show why the listener hears the whisper clearly: each path has the same total length 2a = 6, so the sound reassembles at F at the same instant.",
    mode: 'all', ray: 3, play: true
  }
];
let step = 0;
const elTitle = document.getElementById('stepTitle');
const elText = document.getElementById('stepText');
const elCount = document.getElementById('stepCount');

function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  elTitle.textContent = s.title;
  elText.textContent = s.text;
  elCount.textContent = (step + 1) + ' / ' + STEPS.length;
  mode = s.mode;
  selected = s.ray;
  setPlaying(s.play);
  refresh();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(step - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(step + 1));
goToStep(0);

/* ── pulse animation loop ───────────────────────────────────────────────── */
const PERIOD = 2800;
const tmpA = new THREE.Vector3();
function tick() {
  requestAnimationFrame(tick);
  if (!playing) return;
  const u = ((performance.now() - clock0) % PERIOD) / PERIOD;
  rays.forEach((g, i) => {
    const show = (mode === 'all') || (i === selected);
    const p = pulses[i];
    p.visible = show;
    if (!show) return;
    const dd = u * 6.0;
    const { P, L1, L2 } = g.userData;
    if (dd <= L1) tmpA.lerpVectors(Fp, P, dd / L1);
    else tmpA.lerpVectors(P, Ff, Math.min(1, (dd - L1) / L2));
    p.position.copy(tmpA);
  });
  const lw = u < 0.18 ? u / 0.18 : -1;
  ringLaunch.visible = lw >= 0;
  if (lw >= 0) {
    const s = 0.4 + lw * 2.2;
    ringLaunch.scale.set(s, 1, s);
    ringLaunch.material.opacity = 0.75 * (1 - lw);
  }
  const aw = u > 0.82 ? (u - 0.82) / 0.18 : -1;
  ringArrive.visible = aw >= 0;
  if (aw >= 0) {
    const s = 2.6 - aw * 2.2;
    ringArrive.scale.set(s, 1, s);
    ringArrive.material.opacity = 0.35 + 0.5 * aw;
  }
}
tick();
// @FIGURE_CODE_END

